    image_patch = ImagePatch(image)
    woman_patches = image_patch.find("woman")
    mirror_patches = image_patch.find("mirror")

    if not woman_patches or not mirror_patches:
        return image_patch

    woman_patch = woman_patches[0]
    mirror_patch = mirror_patches[0]

    # Find the part of the woman that is inside the mirror
    woman_in_mirror = []
    for y in range(woman_patch.upper, woman_patch.lower):
        for x in range(woman_patch.left, woman_patch.right):
            if mirror_patch.contains(x, y):
                woman_in_mirror.append((x, y))

    if not woman_in_mirror:
